// Middleware is a server that delegates to another server.
type Middleware interface {
	Next() Server
}

// Iter yields `s` and, as long as they are middlewares, the servers behind
// it, from the outermost one to the one that handles the request.
func Iter(s Server) iter.Seq[Server] {
	return func(yield func(Server) bool) {
		for s != nil {
			if !yield(s) {
				return
			}

			mw, ok := s.(Middleware)
			if !ok {
				return
			}

			s = mw.Next()
		}
	}
}

