// `T` is unconstrained on purpose. The question is asked two ways -- by the
// concrete type of a layer, and by an interface naming the one thing the
// caller needs -- and a constraint of Server would admit only the first,
// since an interface with one method on it does not implement Server. The
// cost is that a `T` no server could ever be is a legal question with a
// false answer.
func Find[T any](s Server) (T, bool) {
	for s := range Iter(s) {
		if v, ok := s.(T); ok {
			return v, true
		}
	}

	var zero T
	return zero, false
}

// SinkOf returns the server the stack ends at, which is the one the others
// were built in front of and the only one that answers out of a database
// rather than by asking somebody else.
//
// It is the same server [Build] was given, and it is named the same way.
// What is at the end is not always what a caller means, though: reach for
// [Find] when there is a particular server in mind, and keep this for when
// the stack itself is the subject.
func SinkOf(s Server) Server {
	for v := range Iter(s) {
		s = v
	}
	return s
}

// Overlay is a middleware that forwards every service it does not override
// to the next server. Embed it to implement only the services of interest:
//
//	type Server struct {
//		Overlay
//	}
//
//	func (s Server) Tenant() TenantServiceServer { ... }
type Overlay struct {
	Server
}

func NewOverlay(next Server) Overlay {
	return Overlay{next}
}

func (s Overlay) Next() Server {
	return s.Server
}

// Builder makes a server that sits in front of `next`. Building may fail
// since a server is free to open the resources it needs, or to reject the
// settings it was given, while it is made.
type Builder interface {
	Build(next Server) (Server, error)
}

type BuilderFunc func(next Server) (Server, error)

func (f BuilderFunc) Build(next Server) (Server, error) {
	return f(next)
}

// Build stacks the given middlewares on top of `sink`. Each builder wraps
// the result of the previous one, so the last builder given handles the
// request first:
//
//	Build(sink, core.Build(), log.Build())
//	// log -> core -> sink
//
// It stops at the first builder that fails, reporting it by its type.
func Build(sink Server, mws ...Builder) (Server, error) {
	s := sink
	for _, mw := range mws {
		v, err := mw.Build(s)
		if err != nil {
			return nil, fmt.Errorf("%T: %w", mw, err)
		}

		s = v
	}

	return s, nil
}
